    <div class="col-md-6"><label class="form-label">Equipamientos <span class="text-muted">(opcional)</span></label><div class="input-group"><input id="equipamientosTexto" class="form-control" value="{{ $editing ? ($ejercicio->equipamiento ?? '') : '' }}" placeholder="Sin equipamientos seleccionados" readonly data-optional="true"><button class="btn btn-outline-primary" type="button" data-bs-toggle="modal" data-bs-target="#modalEquipamientos">Elegir</button></div><div id="equipamientosInputs">@foreach($equipamientosSeleccionados as $id)<input type="hidden" name="equipamiento_ids[]" value="{{ $id }}">@endforeach</div></div>
