    <div class="col-12"><label class="form-label">Video <span class="text-muted">(opcional)</span></label><input type="url" class="form-control" name="video_url" data-optional="true" value="{{ old('video_url', $ejercicio->video_url ?? '') }}"></div>
</div>
<div class="modal fade" id="modalEquipamientos" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Elegir equipamientos</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p class="text-muted small">Marca todos los equipamientos que utiliza este ejercicio.</p><div class="vstack gap-2">@foreach($equipamientos as $item)<label class="border rounded p-2 d-flex gap-2 align-items-center"><input class="form-check-input equipo-check" type="checkbox" value="{{ $item->id }}" data-nombre="{{ $item->nombre }}" @checked(in_array((string) $item->id, array_map('strval', $equipamientosSeleccionados), true))><span>{{ $item->nombre }}</span></label>@endforeach</div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button id="confirmarEquipamientos" type="button" class="btn btn-primary" data-bs-dismiss="modal">Confirmar selección</button></div></div></div></div>
@push('scripts')<script>document.getElementById('confirmarEquipamientos')?.addEventListener('click',()=>{const checks=[...document.querySelectorAll('.equipo-check:checked')],inputs=document.getElementById('equipamientosInputs');inputs.innerHTML=checks.map(x=>`<input type="hidden" name="equipamiento_ids[]" value="${x.value}">`).join('');document.getElementById('equipamientosTexto').value=checks.map(x=>x.dataset.nombre).join(', ')||'Sin equipamientos seleccionados'});</script>@endpush
